export function listSurfaceRecipesByStyle(styleId: LuxuryStyleId): readonly SurfaceRecipe[] {
  return SURFACE_RECIPE_CATALOG.filter((entry) => entry.styleId === styleId);
}

export function listSurfaceRecipesBySurface(surfaceId: SurfaceId): readonly SurfaceRecipe[] {
  return SURFACE_RECIPE_CATALOG.filter((entry) => entry.surfaceId === surfaceId);
}
